const categories = ["อาหาร", "เดินทาง", "ช้อปปิ้ง", "บันเทิง", "บิล/บ้าน", "สุขภาพ", "การศึกษา", "อื่น ๆ"];
const categoryMeta = (category: string) => {
  const value = category.trim().toLowerCase();
  if (value.includes("อาหาร") || value.includes("food") || value.includes("กิน")) return { icon: "🍜", color: "#ff8b7b" };
  if (value.includes("เดินทาง") || value.includes("รถ") || value.includes("travel") || value.includes("transport")) return { icon: "🚕", color: "#ffbd72" };
  if (value.includes("ช้อป") || value.includes("shopping") || value.includes("ซื้อ")) return { icon: "🛍️", color: "#9b7bff" };
  if (value.includes("บันเทิง") || value.includes("เกม") || value.includes("entertain")) return { icon: "🎮", color: "#67d7ca" };
  if (value.includes("บิล") || value.includes("บ้าน") || value.includes("bill") || value.includes("home")) return { icon: "🏠", color: "#b8f35b" };
  if (value.includes("สุขภาพ") || value.includes("health") || value.includes("หมอ")) return { icon: "🩺", color: "#ff9e8d" };
  if (value.includes("การศึกษา") || value.includes("เรียน") || value.includes("education")) return { icon: "📚", color: "#b9a6ff" };
  return { icon: "💸", color: "#94a3b8" };
};
