function money(value: number) {
  return `฿${Math.round(value).toLocaleString("th-TH")}`;
}

function ProgressRing({ value, label }: { value: number; label: string }) {
  return <div className="relative h-32 w-32 shrink-0">
    <div className="absolute inset-0 rounded-full" style={{ background: `conic-gradient(#b8f35b ${Math.min(value, 100)}%, #263242 0)` }} />
    <div className="absolute inset-[9px] flex flex-col items-center justify-center rounded-full bg-[#111923]">
      <span className="text-2xl font-black text-white">{Math.round(value)}%</span><span className="text-[10px] uppercase tracking-widest text-slate-400">{label}</span>
    </div>
  </div>;
}

